# FDN Springbloom Druid: "When this creature enters, you may sacrifice a land. If you do, search
# your library for up to two basic land cards, put them onto the battlefield tapped, then
# shuffle."  M21 Crypt Lurker's optional sacrifice of a permanent you control (CHOOSE, a land
# here), "If you do" as Conditional(MAY_DONE) (MAPPER_GUIDE), and FDN Burnished Hart's search
# (QAtMost(2) basic lands onto the battlefield tapped, then shuffle).
ramp = TriggeredAbility(
    event=ZoneChangeEvent(
        from_zone=Zone(kind=ZoneKind.ANY, controller=ControllerRef.ANY),
        to_zone=Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.YOU),
        subject=FAtom(pred=FAtomPred.IS_SOURCE),
    ),
    condition=None,
    effect=Seq(
        steps=(
            OptionalEffect(
                inner=A(Verb.SACRIFICE, {
                    'target': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.CHOOSE,
                        filter=FAnd(
                            children=(
                                FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Land'),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                }),
            ),
            Conditional(
                pred=FAtom(pred=FAtomPred.MAY_DONE),
                then_effect=Seq(
                    steps=(
                        A(Verb.SEARCH, {
                            'cards': Selector(
                                count=QAtMost(n=2),
                                mode=SelectorMode.CHOOSE,
                                filter=FAnd(
                                    children=(
                                        FAtom(pred=FAtomPred.SUPERTYPE_EQ, string_value='Basic'),
                                        FAtom(pred=FAtomPred.TYPE_EQ, string_value='Land'),
                                    ),
                                ),
                                zones=(Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU),),
                            ),
                            'destination': Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.YOU),
                            'tapped_on_enter': True,
                        }),
                        A(Verb.SHUFFLE, {'zone': Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU)}),
                    ),
                ),
            ),
        ),
    ),
)
abilities = [ramp, *compiled]
